export const GALLERY_SOURCE: Record<string, string> = {
  "form-demo.tsx": "import { useState, type FormEvent } from 'react';\nimport { Button } from './button';\nimport { Input } from './input';\nimport { Select } from './select';\nimport './form-demo.css';\n\nexport type FormDemoMode = 'login' | 'signup' | 'password' | 'search' | 'filter' | 'date' | 'lot' | 'equipment' | 'edit' | 'file' | 'image';\n\nconst LABELS: Record<FormDemoMode, string> = {\n  login: '로그인 폼', signup: '회원가입 폼', password: '비밀번호 변경 폼', search: '검색 폼', filter: '필터 폼', date: '날짜 범위 폼', lot: 'LOT 등록 폼', equipment: '설비 등록 폼', edit: '공통 수정 폼', file: '파일 업로드 폼', image: '이미지 업로드 폼',\n};\n\nexport function FormDemo({ mode = 'login' }: { mode?: FormDemoMode }) {\n  const [submitted, setSubmitted] = useState(false);\n  const [fileName, setFileName] = useState('');\n  const submit = (event: FormEvent<HTMLFormElement>) => { event.preventDefault(); setSubmitted(true); };\n  const file = mode === 'file' || mode === 'image';\n  return <form className=\"form-demo\" onSubmit={submit}>\n    <div className=\"form-demo-heading\"><div><strong>{LABELS[mode]}</strong><span>실제 컴포넌트</span></div><small>Light 기본</small></div>\n    <div className=\"form-demo-fields\">\n      {mode === 'login' && <><Input label=\"이메일 또는 사번\" placeholder=\"user@example.com\" required /><Input label=\"비밀번호\" type=\"password\" placeholder=\"비밀번호 입력\" required /></>}\n      {mode === 'signup' && <><Input label=\"이름\" placeholder=\"홍길동\" required /><Input label=\"이메일\" type=\"email\" placeholder=\"user@example.com\" required /><Input label=\"비밀번호\" type=\"password\" placeholder=\"8자 이상\" required /></>}\n      {mode === 'password' && <><Input label=\"현재 비밀번호\" type=\"password\" required /><Input label=\"새 비밀번호\" type=\"password\" hint=\"영문·숫자·특수문자 포함 8자 이상\" required /></>}\n      {mode === 'search' && <Input label=\"검색어\" placeholder=\"LOT 번호, 품목명 검색\" />}\n      {mode === 'filter' && <><Select label=\"상태\" options={['전체', '진행', '완료', '이상']} placeholder=\"상태 선택\" /><Select label=\"공정\" options={['전체', '노광', '식각', '검사']} placeholder=\"공정 선택\" /></>}\n      {mode === 'date' && <><Input label=\"시작일\" type=\"date\" defaultValue=\"2026-08-01\" required /><Input label=\"종료일\" type=\"date\" defaultValue=\"2026-08-26\" required /></>}\n      {mode === 'lot' && <><Input label=\"LOT 번호\" placeholder=\"LOT-24086\" required /><Input label=\"수량\" type=\"number\" placeholder=\"0\" required /><Select label=\"설비\" options={['EQ-101', 'EQ-102', 'EQ-201']} placeholder=\"설비 선택\" /></>}\n      {mode === 'equipment' && <><Input label=\"설비 코드\" placeholder=\"EQ-301\" required /><Input label=\"설비명\" placeholder=\"세정 설비\" required /><Select label=\"운영 상태\" options={['가동', '점검', '중지']} placeholder=\"상태 선택\" /></>}\n      {mode === 'edit' && <><Input label=\"이름\" defaultValue=\"기존 데이터\" required /><Input label=\"설명\" defaultValue=\"수정할 설명을 입력하세요.\" /></>}\n      {file && <label className=\"form-demo-upload\"><span>{mode === 'image' ? '이미지 파일' : '첨부 파일'}</span><input type=\"file\" accept={mode === 'image' ? 'image/*' : undefined} onChange={(event) => setFileName(event.target.files?.[0]?.name ?? '')} />{fileName ? <small>{fileName}</small> : <small>파일을 선택하세요</small>}</label>}\n    </div>\n    <div className=\"form-demo-actions\"><Button type=\"submit\">{mode === 'search' || mode === 'filter' || mode === 'date' ? '조회' : mode === 'login' ? '로그인' : file ? '업로드' : '저장'}</Button><Button type=\"button\" variant=\"secondary\" onClick={() => setSubmitted(false)}>초기화</Button></div>\n    {submitted ? <p className=\"form-demo-success\" role=\"status\">입력값을 확인하고 제출할 수 있습니다.</p> : null}\n  </form>;\n}",
  "form-demo.css": ".form-demo { width: 100%; padding: 18px; border: 1px solid #dbe3ee; border-radius: 12px; background: #f8fafc; color: #0f172a; font-family: inherit; }\n.form-demo-heading { display: flex; align-items: center; justify-content: space-between; padding-bottom: 14px; border-bottom: 1px solid #e2e8f0; }\n.form-demo-heading div { display: flex; align-items: center; gap: 9px; }\n.form-demo-heading strong { font-size: 16px; }\n.form-demo-heading span { padding: 4px 8px; border-radius: 999px; background: #dbeafe; color: #1d4ed8; font-size: 11px; font-weight: 800; }\n.form-demo-heading small { color: #64748b; font-size: 11px; font-weight: 800; }\n.form-demo-fields { display: grid; grid-template-columns: minmax(0, 520px); gap: 14px; padding: 18px 0; }\n.form-demo-fields .field, .form-demo-upload { min-width: 0; }\n.form-demo-upload { display: flex; min-height: 78px; flex-direction: column; justify-content: center; gap: 7px; padding: 10px 12px; border: 1px dashed #93c5fd; border-radius: 8px; background: #eff6ff; color: #334155; font-size: 12px; font-weight: 800; }\n.form-demo-upload input { max-width: 100%; font-size: 12px; }\n.form-demo-upload small { color: #64748b; font-weight: 600; }\n.form-demo-actions { display: flex; gap: 8px; }\n.form-demo-success { margin: 12px 0 0; color: #047857; font-size: 12px; font-weight: 800; }",
  "layout-demo.tsx": "import './layout-demo.css';\n\ntype LayoutMode = 'grid' | 'responsive' | 'dashboard' | 'list-detail' | 'master-detail';\n\nexport function LayoutDemo({ mode = 'grid' }: { mode?: LayoutMode }) {\n  if (mode === 'dashboard') return <div className=\"layout-demo layout-dashboard\"><div className=\"layout-stat\"><small>오늘 생산</small><strong>1,284</strong><span>+8.4%</span></div><div className=\"layout-stat\"><small>진행 LOT</small><strong>24</strong><span>정상</span></div><div className=\"layout-stat\"><small>가동 설비</small><strong>18/20</strong><span>90%</span></div><div className=\"layout-panel layout-panel-wide\"><strong>생산 현황</strong><div className=\"layout-bars\"><i style={{height:'48%'}}/><i style={{height:'72%'}}/><i style={{height:'58%'}}/><i style={{height:'88%'}}/><i style={{height:'66%'}}/></div></div></div>;\n  if (mode === 'list-detail') return <div className=\"layout-demo layout-split\"><div className=\"layout-list\"><strong>LOT 목록</strong><button>LOT-24081</button><button className=\"is-active\">LOT-24082</button><button>LOT-24083</button></div><div className=\"layout-detail\"><small>선택한 LOT</small><strong>LOT-24082</strong><p>제품 PKT-A100 · 식각 공정 · 진행 중</p></div></div>;\n  if (mode === 'master-detail') return <div className=\"layout-demo layout-split layout-master\"><div className=\"layout-list\"><strong>설비</strong><button className=\"is-active\">EQ-101 · 노광</button><button>EQ-102 · 식각</button><button>EQ-201 · 검사</button></div><div className=\"layout-detail\"><small>설비 상세</small><strong>EQ-101</strong><div className=\"layout-detail-grid\"><span>상태</span><b>가동</b><span>담당 라인</span><b>1라인</b></div></div></div>;\n  return <div className={`layout-demo ${mode === 'responsive' ? 'layout-responsive' : 'layout-grid'}`}><div>영역 A</div><div>영역 B</div><div>영역 C</div><div>영역 D</div>{mode === 'responsive' ? <small>창 너비에 따라 4열 → 2열 → 1열로 줄어듭니다.</small> : null}</div>;\n}",
  "layout-demo.css": ".layout-demo { width: 100%; padding: 16px; border: 1px solid #dbe3ee; border-radius: 12px; background: #f8fafc; color: #0f172a; font-family: inherit; }\n.layout-grid, .layout-responsive { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px; }\n.layout-grid > div, .layout-responsive > div { display: grid; min-height: 58px; place-items: center; border: 1px solid #bfdbfe; border-radius: 9px; background: #dbeafe; color: #1d4ed8; font-size: 13px; font-weight: 800; }\n.layout-responsive small { grid-column: 1 / -1; color: #64748b; font-size: 12px; font-weight: 700; }\n.layout-dashboard { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; }\n.layout-stat, .layout-panel { padding: 14px; border: 1px solid #e2e8f0; border-radius: 9px; background: #fff; }\n.layout-stat { display: grid; gap: 6px; } .layout-stat small, .layout-detail small { color: #64748b; font-size: 11px; font-weight: 800; } .layout-stat strong { font-size: 22px; } .layout-stat span { color: #047857; font-size: 11px; font-weight: 800; }\n.layout-panel-wide { grid-column: 1 / -1; } .layout-bars { display: flex; align-items: end; gap: 12px; height: 80px; margin-top: 12px; } .layout-bars i { display: block; width: 32px; border-radius: 5px 5px 0 0; background: #60a5fa; }\n.layout-split { display: grid; grid-template-columns: 190px minmax(0, 1fr); gap: 12px; } .layout-list, .layout-detail { display: grid; align-content: start; gap: 8px; padding: 14px; border: 1px solid #e2e8f0; border-radius: 9px; background: #fff; } .layout-list strong { margin-bottom: 4px; font-size: 14px; } .layout-list button { padding: 9px 10px; border: 0; border-radius: 7px; background: #f8fafc; color: #475569; text-align: left; font: inherit; font-size: 12px; font-weight: 700; cursor: pointer; } .layout-list button.is-active { background: #2563eb; color: #fff; } .layout-detail { align-content: start; } .layout-detail > strong { font-size: 20px; } .layout-detail p { margin: 2px 0; color: #475569; font-size: 13px; font-weight: 600; } .layout-detail-grid { display: grid; grid-template-columns: 90px 1fr; gap: 8px; margin-top: 10px; font-size: 12px; } .layout-detail-grid span { color: #64748b; } .layout-detail-grid b { color: #0f172a; }\n@media (max-width: 620px) { .layout-grid, .layout-responsive { grid-template-columns: repeat(2, minmax(0, 1fr)); } .layout-dashboard { grid-template-columns: 1fr; } .layout-panel-wide { grid-column: auto; } .layout-split { grid-template-columns: 1fr; } }",
  "state-demo.tsx": "import { useState } from 'react';\nimport './state-demo.css';\n\ntype StateMode = 'hover'|'dropdown'|'accordion'|'animation'|'loading'|'skeleton'|'empty'|'error'|'toast'|'combo';\nexport function StateDemo({ mode = 'hover' }: { mode?: StateMode }) {\n  const [open, setOpen] = useState(mode === 'accordion'); const [show, setShow] = useState(false);\n  if (mode === 'dropdown') return <div className=\"state-demo\"><button className=\"state-trigger\" onClick={() => setShow(!show)}>작업 메뉴 ▾</button>{show && <div className=\"state-menu\"><button>수정</button><button>복제</button><button>삭제</button></div>}</div>;\n  if (mode === 'accordion') return <div className=\"state-demo state-accordion\"><button onClick={() => setOpen(!open)}>상세 설명 <span>{open ? '−' : '+'}</span></button>{open && <p>접근성 있는 버튼으로 콘텐츠를 열고 닫습니다. 현재 상태는 시각적 변화와 함께 전달됩니다.</p>}</div>;\n  if (mode === 'loading') return <div className=\"state-demo state-message\"><span className=\"state-spinner\"/> 데이터를 불러오는 중입니다…</div>;\n  if (mode === 'skeleton') return <div className=\"state-demo state-skeleton\"><i/><i/><i/></div>;\n  if (mode === 'empty') return <div className=\"state-demo state-message\"><strong>표시할 데이터가 없습니다.</strong><span>검색 조건을 바꾸거나 새 항목을 추가해 보세요.</span></div>;\n  if (mode === 'error') return <div className=\"state-demo state-error\"><strong>데이터를 불러오지 못했습니다.</strong><span>잠시 후 다시 시도해 주세요.</span><button onClick={() => setShow(true)}>다시 시도</button>{show && <small>재시도 요청을 보냈습니다.</small>}</div>;\n  if (mode === 'toast') return <div className=\"state-demo\"><button className=\"state-trigger\" onClick={() => setShow(true)}>저장 완료 토스트 보기</button>{show && <div className=\"state-toast\" role=\"status\">✓ 저장되었습니다 <button onClick={() => setShow(false)}>×</button></div>}</div>;\n  if (mode === 'animation') return <div className=\"state-demo\"><div className=\"state-pulse\">상태 변화</div></div>;\n  if (mode === 'combo') return <div className=\"state-demo state-combo\"><span className=\"state-spinner\"/><strong>저장 중…</strong><button onClick={() => setShow(true)}>완료 상태 보기</button>{show && <em>저장 완료</em>}</div>;\n  return <div className=\"state-demo\"><button className=\"state-hover\">마우스를 올려보세요</button><span className=\"state-tooltip\">추가 설명</span></div>;\n}",
  "state-demo.css": ".state-demo { position:relative; display:flex; width:100%; min-height:132px; align-items:flex-start; gap:10px; padding:20px 18px; border:0; border-radius:0; background:transparent; color:#334155; font-family:inherit; font-size:13px; font-weight:700; }\n.state-trigger,.state-hover,.state-accordion button,.state-error button,.state-combo button { border:1px solid #bfdbfe; border-radius:8px; background:#fff; color:#1d4ed8; padding:9px 13px; font:inherit; cursor:pointer; }.state-trigger:hover,.state-hover:hover { background:#dbeafe; transform:translateY(-1px); }.state-tooltip { opacity:0; padding:6px 9px; border-radius:6px; background:#1e293b; color:#fff; font-size:11px; transition:opacity .15s; }.state-demo:has(.state-hover:hover) .state-tooltip { opacity:1; }\n.state-menu { position:absolute; top:64px; left:18px; z-index:1; display:grid; min-width:130px; padding:5px; border:1px solid #e2e8f0; border-radius:8px; background:#fff; box-shadow:0 8px 20px #0f172a1c; }.state-menu button { border:0; background:#fff; padding:8px 10px; text-align:left; font:inherit; font-size:12px; cursor:pointer; }.state-menu button:hover { background:#eff6ff; color:#1d4ed8; }\n.state-accordion { display:block; padding:0; overflow:hidden; background:#fff; }.state-accordion button { display:flex; width:100%; justify-content:space-between; border:0; border-radius:0; text-align:left; }.state-accordion p { margin:0; padding:13px; color:#64748b; font-size:12px; line-height:1.6; }\n.state-spinner { width:16px; height:16px; border:2px solid #bfdbfe; border-top-color:#2563eb; border-radius:50%; animation:state-spin .7s linear infinite; } @keyframes state-spin { to{transform:rotate(360deg)} }\n.state-skeleton { display:grid; align-content:center; gap:9px; }.state-skeleton i { display:block; width:70%; height:11px; border-radius:5px; background:linear-gradient(90deg,#e2e8f0,#f8fafc,#e2e8f0); background-size:200% 100%; animation:state-shimmer 1.2s infinite; }.state-skeleton i:nth-child(2){width:90%}.state-skeleton i:nth-child(3){width:55%} @keyframes state-shimmer { to{background-position:-200% 0} }\n.state-message { flex-direction:column; align-items:flex-start; }.state-message span { color:#64748b; font-size:12px; }.state-error { flex-wrap:wrap; color:#b91c1c; background:#fff7f7; border-color:#fecaca; }.state-error span,.state-error small { color:#7f1d1d; font-size:12px; }.state-error button { color:#b91c1c; border-color:#fecaca; }.state-toast { position:absolute; right:16px; bottom:12px; padding:10px 12px; border-radius:8px; background:#047857; color:#fff; font-size:12px; }.state-toast button { border:0; background:transparent; color:#fff; font-size:16px; cursor:pointer; }.state-pulse { padding:13px 18px; border-radius:8px; background:#2563eb; color:#fff; animation:state-pulse 1.5s infinite; } @keyframes state-pulse { 50%{box-shadow:0 0 0 8px #2563eb22} }.state-combo em { margin-left:auto; color:#047857; font-style:normal; }",
  "pagination.tsx": "import './pagination.css';\n\ntype PaginationProps = { page: number; pageCount: number; onPageChange: (page: number) => void; compact?: boolean };\n\nfunction pageItems(page: number, pageCount: number): Array<number | 'ellipsis'> {\n  if (pageCount <= 7) return Array.from({ length: pageCount }, (_, index) => index + 1);\n  if (page <= 4) return [1, 2, 3, 4, 5, 'ellipsis', pageCount];\n  if (page >= pageCount - 3) return [1, 'ellipsis', pageCount - 4, pageCount - 3, pageCount - 2, pageCount - 1, pageCount];\n  return [1, 'ellipsis', page - 1, page, page + 1, 'ellipsis', pageCount];\n}\n\nexport function Pagination({ page, pageCount, onPageChange, compact = false }: PaginationProps) {\n  const safePage = Math.min(Math.max(page, 1), Math.max(pageCount, 1));\n  const items = pageItems(safePage, pageCount);\n  const go = (nextPage: number) => onPageChange(Math.min(Math.max(nextPage, 1), pageCount));\n  if (pageCount <= 1) return null;\n  return <nav className={`pagination${compact ? ' pagination-compact' : ''}`} aria-label=\"페이지 이동\"><button type=\"button\" aria-label=\"첫 페이지\" disabled={safePage === 1} onClick={() => go(1)}>«</button><button type=\"button\" aria-label=\"이전 페이지\" disabled={safePage === 1} onClick={() => go(safePage - 1)}>‹</button><ol>{items.map((item, index) => item === 'ellipsis' ? <li key={`ellipsis-${index}`}><span aria-hidden=\"true\">…</span></li> : <li key={item}><button type=\"button\" aria-label={`${item}페이지`} aria-current={item === safePage ? 'page' : undefined} onClick={() => go(item)}>{item}</button></li>)}</ol><button type=\"button\" aria-label=\"다음 페이지\" disabled={safePage === pageCount} onClick={() => go(safePage + 1)}>›</button><button type=\"button\" aria-label=\"마지막 페이지\" disabled={safePage === pageCount} onClick={() => go(pageCount)}>»</button></nav>;\n}\n",
  "pagination.css": "/* 외부 UI 라이브러리 없이 쓰는 Pagination 스타일. Light 테마를 기본으로 한다. */\n.pagination { display: inline-flex; align-items: center; gap: 4px; color: #475569; font-family: inherit; }\n.pagination > button, .pagination ol button { display: grid; place-items: center; min-width: 32px; height: 32px; padding: 0 8px; border: 1px solid #e2e8f0; border-radius: 7px; background: #fff; color: #475569; font: inherit; font-size: 13px; font-weight: 800; cursor: pointer; }\n.pagination > button:hover:not(:disabled), .pagination ol button:hover { border-color: #93c5fd; background: #eff6ff; color: #1d4ed8; }\n.pagination button:focus-visible { outline: 2px solid #2563eb; outline-offset: 2px; }\n.pagination button:disabled { background: #f8fafc; color: #cbd5e1; cursor: not-allowed; }\n.pagination ol { display: flex; align-items: center; gap: 4px; margin: 0 2px; padding: 0; list-style: none; }\n.pagination ol button[aria-current='page'] { border-color: #1d4ed8; background: #1d4ed8; color: #fff; }\n.pagination ol span { display: grid; min-width: 22px; height: 32px; place-items: center; color: #94a3b8; }\n.pagination-compact { gap: 2px; }\n.pagination-compact > button, .pagination-compact ol button { min-width: 28px; height: 28px; font-size: 12px; }\n.pagination-compact ol { gap: 2px; }\n",
  "pagination-demo.tsx": "import { useState } from 'react';\nimport { Pagination } from './pagination';\nimport './pagination.css';\n\nexport function PaginationDemo({ compact = false }: { compact?: boolean }) {\n  const [page, setPage] = useState(4);\n  return <div style={{ display: 'grid', gap: 16, justifyItems: 'center', width: '100%', padding: 20, border: '1px solid #e2e8f0', borderRadius: 10, background: '#fff' }}><Pagination page={page} pageCount={12} onPageChange={setPage} compact={compact} /><span style={{ color: '#64748b', fontSize: 13, fontWeight: 700 }}>현재 페이지: {page} / 12</span></div>;\n}\n",
  "breadcrumb.tsx": "import type { ReactNode } from 'react';\nimport './breadcrumb.css';\n\nexport type BreadcrumbItem = { id: string; label: string; href?: string };\n\ntype BreadcrumbProps = { items: BreadcrumbItem[]; compact?: boolean; onNavigate?: (id: string) => void; separator?: ReactNode };\n\nexport function Breadcrumb({ items, compact = false, onNavigate, separator = '/' }: BreadcrumbProps) {\n  const visibleItems = compact && items.length > 3 ? [items[0], { id: 'ellipsis', label: '…' }, ...items.slice(-2)] : items;\n  return (\n    <nav className={`breadcrumb${compact ? ' breadcrumb-compact' : ''}`} aria-label=\"breadcrumb\">\n      <ol>{visibleItems.map((item, index) => {\n        const isCurrent = index === visibleItems.length - 1;\n        const isEllipsis = item.id === 'ellipsis';\n        return <li key={`${item.id}-${index}`}>{isCurrent || isEllipsis ? <span aria-current={isCurrent ? 'page' : undefined} className={isEllipsis ? 'breadcrumb-ellipsis' : undefined}>{item.label}</span> : <a href={item.href ?? '#'} onClick={(event) => { if (!item.href || onNavigate) event.preventDefault(); onNavigate?.(item.id); }}>{item.label}</a>}{!isCurrent ? <span className=\"breadcrumb-separator\" aria-hidden=\"true\">{separator}</span> : null}</li>;\n      })}</ol>\n    </nav>\n  );\n}\n",
  "breadcrumb.css": "/* 외부 UI 라이브러리 없이 쓰는 Breadcrumb 스타일. Light 테마를 기본으로 한다. */\n.breadcrumb { width: 100%; color: #64748b; font-family: inherit; }\n.breadcrumb ol { display: flex; align-items: center; gap: 8px; margin: 0; padding: 0; list-style: none; }\n.breadcrumb li { display: inline-flex; min-width: 0; align-items: center; gap: 8px; font-size: 13px; font-weight: 700; }\n.breadcrumb a { overflow: hidden; color: #64748b; text-decoration: none; text-overflow: ellipsis; white-space: nowrap; }\n.breadcrumb a:hover { color: #1d4ed8; text-decoration: underline; text-underline-offset: 3px; }\n.breadcrumb li:last-child > span[aria-current='page'] { overflow: hidden; color: #0f172a; font-weight: 800; text-overflow: ellipsis; white-space: nowrap; }\n.breadcrumb-separator { flex: 0 0 auto; color: #cbd5e1; font-weight: 500; }\n.breadcrumb-ellipsis { color: #94a3b8; }\n.breadcrumb a:focus-visible { outline: 2px solid #2563eb; outline-offset: 3px; border-radius: 3px; }\n.breadcrumb-compact ol { gap: 6px; }\n.breadcrumb-compact li { gap: 6px; font-size: 12px; }\n",
  "breadcrumb-demo.tsx": "import { useState } from 'react';\nimport { Breadcrumb, type BreadcrumbItem } from './breadcrumb';\nimport './breadcrumb.css';\n\nconst ITEMS: BreadcrumbItem[] = [{ id: 'home', label: '홈', href: '/' }, { id: 'production', label: '생산 관리', href: '/production' }, { id: 'lot', label: 'LOT 조회', href: '/production/lots' }, { id: 'detail', label: 'LOT-24084 상세' }];\n\nexport function BreadcrumbDemo({ compact = false }: { compact?: boolean }) {\n  const [selectedId, setSelectedId] = useState('detail');\n  return <div style={{ width: '100%', padding: '18px 20px', border: '1px solid #e2e8f0', borderRadius: 10, background: '#fff' }}><Breadcrumb items={ITEMS} compact={compact} onNavigate={setSelectedId} /><p style={{ margin: '18px 0 0', color: '#475569', fontSize: 13, fontWeight: 600 }}>현재 위치: <strong style={{ color: '#1d4ed8' }}>{selectedId}</strong></p></div>;\n}\n",
  "badge.tsx": "import type { ReactNode } from 'react';\nimport './badge.css';\n\ntype BadgeTone = 'neutral' | 'info' | 'success' | 'warning' | 'danger';\ntype BadgeSize = 'sm' | 'md';\n\ntype BadgeProps = {\n  tone?: BadgeTone;\n  size?: BadgeSize;\n  /** 상태 표시용 점을 앞에 붙인다. */\n  dot?: boolean;\n  children: ReactNode;\n};\n\nexport function Badge({ tone = 'neutral', size = 'md', dot = false, children }: BadgeProps) {\n  return (\n    <span className={`badge badge-${tone} badge-${size}`}>\n      {dot ? <span className=\"badge-dot\" /> : null}\n      {children}\n    </span>\n  );\n}\n",
  "badge.css": "/* 외부 UI 라이브러리 없이 쓰는 Badge 스타일. */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  gap: 5px;\n  border-radius: 999px;\n  font-family: inherit;\n  font-weight: 800;\n  line-height: 1;\n  white-space: nowrap;\n}\n.badge-sm { padding: 4px 9px; font-size: 11px; }\n.badge-md { padding: 6px 11px; font-size: 12px; }\n\n.badge-neutral { background: #e2e8f0; color: #334155; }\n.badge-info    { background: #dbeafe; color: #1d4ed8; }\n.badge-success { background: #d1fae5; color: #047857; }\n.badge-warning { background: #fef3c7; color: #b45309; }\n.badge-danger  { background: #fee2e2; color: #b91c1c; }\n\n.badge-dot { width: 6px; height: 6px; border-radius: 999px; background: currentColor; }\n",
  "button.tsx": "import type { ButtonHTMLAttributes, ReactNode } from 'react';\nimport './button.css';\n\ntype ButtonVariant = 'primary' | 'secondary' | 'ghost' | 'danger';\ntype ButtonSize = 'sm' | 'md' | 'lg';\n\ntype ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {\n  variant?: ButtonVariant;\n  size?: ButtonSize;\n  loading?: boolean;\n  children: ReactNode;\n};\n\nexport function Button({\n  variant = 'primary',\n  size = 'md',\n  loading = false,\n  disabled,\n  children,\n  className = '',\n  ...props\n}: ButtonProps) {\n  return (\n    <button\n      type=\"button\"\n      disabled={disabled || loading}\n      className={`btn btn-${variant} btn-${size} ${className}`}\n      {...props}\n    >\n      {loading ? '처리 중…' : children}\n    </button>\n  );\n}\n",
  "button.css": "/* 외부 UI 라이브러리 없이 쓰는 Button 스타일. 폐쇄망에서도 이 파일만 복사하면 된다. */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  border: 0;\n  border-radius: 8px;\n  font-family: inherit;\n  font-weight: 800;\n  line-height: 1;\n  cursor: pointer;\n  transition: background-color 0.15s ease, box-shadow 0.15s ease;\n}\n\n.btn:disabled { opacity: 0.45; cursor: not-allowed; }\n\n.btn-sm { padding: 7px 12px; font-size: 12px; }\n.btn-md { padding: 9px 16px; font-size: 13px; }\n.btn-lg { padding: 12px 22px; font-size: 15px; }\n\n.btn-primary { background: #2563eb; color: #fff; }\n.btn-primary:not(:disabled):hover { background: #1d4ed8; }\n\n.btn-secondary { background: #e2e8f0; color: #1e293b; }\n.btn-secondary:not(:disabled):hover { background: #cbd5e1; }\n\n.btn-ghost { background: transparent; color: #334155; box-shadow: inset 0 0 0 1px #cbd5e1; }\n.btn-ghost:not(:disabled):hover { background: #f1f5f9; }\n\n.btn-danger { background: #dc2626; color: #fff; }\n.btn-danger:not(:disabled):hover { background: #b91c1c; }\n",
  "header.tsx": "import { useEffect, useId, useRef, useState, type ReactNode } from 'react';\nimport './header.css';\n\nexport type HeaderNavItem = {\n  id: string;\n  label: string;\n  /** 라우터를 쓰면 실제 경로를 넣는다. 없으면 '#'로 떨어진다. */\n  href?: string;\n};\n\ntype HeaderProps = {\n  brand: string;\n  items: HeaderNavItem[];\n  /** 현재 페이지. 보통 라우터가 쥐고 있으므로 밖에서 받는다. */\n  activeId: string;\n  onSelect: (id: string) => void;\n  /** 검색을 헤더에 둘지. 화면 성격에 따라 다르므로 밖에서 정한다. */\n  search?: boolean;\n  /** 스크롤해도 위에 붙어 있게 한다. 표를 길게 보는 화면에서 특히 쓸모 있다. */\n  sticky?: boolean;\n  dense?: boolean;\n  user?: { name: string; role: string };\n  /** nav 랜드마크의 이름. 사이드바가 함께 있는 화면이면 서로 다르게 준다. */\n  label?: string;\n  /** 건너뛰기 링크가 가리킬 본문 요소의 id. */\n  mainId?: string;\n  onSignOut?: () => void;\n  actions?: ReactNode;\n};\n\n/**\n * 골격 요약\n * - 바깥은 <header>. 페이지에 하나만 두면 banner 랜드마크가 된다. 둘 이상이면 랜드마크가 아니게 된다.\n * - 첫 초점은 \"본문으로 건너뛰기\" 링크다. 키보드 사용자가 메뉴를 매 페이지 훑지 않게 하는 유일한 장치이고,\n *   평소엔 눈에서 빼 두되 초점을 받으면 반드시 보여야 한다.\n * - 메뉴는 <nav aria-label> + ul/li. 사이드바와 같은 이유로 이름을 붙인다. 둘 다 \"내비게이션\"이면 구분이 안 된다.\n * - 현재 페이지는 aria-current=\"page\". 밑줄만 그으면 눈으로만 보이는 상태가 된다.\n * - 검색은 <form role=\"search\">. 이것이 landmark가 되고, 입력에는 보이지 않더라도 label이 있어야 한다.\n * - 아이콘만 있는 버튼은 aria-label이 곧 이름이다. 배지 숫자도 그 이름 안에 넣어야 읽힌다.\n * - 사용자 메뉴는 aria-expanded + aria-haspopup=\"menu\". Esc와 바깥 클릭으로 닫고, 닫을 때 초점을 버튼으로 되돌린다.\n */\nexport function Header({\n  brand,\n  items,\n  activeId,\n  onSelect,\n  search = true,\n  sticky = false,\n  dense = false,\n  user,\n  label = '상단 메뉴',\n  mainId = 'main',\n  onSignOut,\n  actions,\n}: HeaderProps) {\n  const [menuOpen, setMenuOpen] = useState(false);\n  const [query, setQuery] = useState('');\n  const menuRef = useRef<HTMLDivElement>(null);\n  const menuButtonRef = useRef<HTMLButtonElement>(null);\n\n  // 한 화면에 Header가 둘 이상 있어도 id가 엉키지 않도록 인스턴스마다 접두사를 붙인다.\n  const uid = useId();\n  const menuId = `hd-menu-${uid}`;\n  const searchId = `hd-search-${uid}`;\n\n  const closeMenu = (focusBack: boolean) => {\n    setMenuOpen(false);\n    // 초점을 그냥 잃게 두면 키보드 사용자는 문서 맨 위로 돌아간다.\n    if (focusBack) menuButtonRef.current?.focus();\n  };\n\n  useEffect(() => {\n    if (!menuOpen) return;\n    const onPointerDown = (event: PointerEvent) => {\n      if (!menuRef.current?.contains(event.target as Node)) setMenuOpen(false);\n    };\n    const onKeyDown = (event: KeyboardEvent) => {\n      if (event.key === 'Escape') closeMenu(true);\n    };\n    document.addEventListener('pointerdown', onPointerDown);\n    document.addEventListener('keydown', onKeyDown);\n    return () => {\n      document.removeEventListener('pointerdown', onPointerDown);\n      document.removeEventListener('keydown', onKeyDown);\n    };\n  }, [menuOpen]);\n\n  return (\n    <header className={`hd${sticky ? ' is-sticky' : ''}${dense ? ' is-dense' : ''}`}>\n      {/* 마크업 순서상 첫 초점이어야 의미가 있다. 그래서 스타일이 아니라 위치로 보장한다. */}\n      <a className=\"hd-skip\" href={`#${mainId}`}>\n        본문으로 건너뛰기\n      </a>\n\n      <a\n        className=\"hd-brand\"\n        href=\"/\"\n        onClick={(event) => {\n          event.preventDefault();\n          onSelect(items[0]?.id ?? '');\n        }}\n      >\n        <span className=\"hd-mark\" aria-hidden=\"true\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\">\n            <path d=\"M3 20h18M5 20V9l5 3V9l5 3V9l4 3v8\" />\n          </svg>\n        </span>\n        {brand}\n      </a>\n\n      <nav className=\"hd-nav\" aria-label={label}>\n        <ul className=\"hd-list\">\n          {items.map((item) => (\n            <li key={item.id}>\n              <a\n                className=\"hd-link\"\n                href={item.href ?? '#'}\n                // 색이나 밑줄이 아니라 이 속성이 \"현재 페이지\"의 진짜 표시다.\n                aria-current={item.id === activeId ? 'page' : undefined}\n                onClick={(event) => {\n                  // 라우터를 붙이면 이 줄을 지우고 <Link>로 바꾼다.\n                  event.preventDefault();\n                  onSelect(item.id);\n                }}\n              >\n                {item.label}\n              </a>\n            </li>\n          ))}\n        </ul>\n      </nav>\n\n      {search && (\n        // role=\"search\"가 이 폼을 랜드마크로 만든다. div로 감싸면 그 기능이 사라진다.\n        <form\n          className=\"hd-search\"\n          role=\"search\"\n          onSubmit={(event) => {\n            event.preventDefault();\n          }}\n        >\n          {/* placeholder는 label이 아니다. 입력하면 사라지므로 이름으로 쓸 수 없다. */}\n          <label className=\"hd-sr-only\" htmlFor={searchId}>\n            문서 검색\n          </label>\n          <span className=\"hd-search-icon\" aria-hidden=\"true\">\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\">\n              <circle cx=\"11\" cy=\"11\" r=\"7\" />\n              <path d=\"M20 20l-3.5-3.5\" />\n            </svg>\n          </span>\n          <input\n            id={searchId}\n            className=\"hd-input\"\n            type=\"search\"\n            value={query}\n            placeholder=\"LOT 번호, 문서 제목\"\n            onChange={(event) => setQuery(event.target.value)}\n          />\n        </form>\n      )}\n\n      <div className=\"hd-actions\">\n        {actions}\n\n        <button type=\"button\" className=\"hd-icon-button\" aria-label=\"알림 3건\">\n          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\">\n            <path d=\"M18 8a6 6 0 10-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M13.7 21a2 2 0 01-3.4 0\" />\n          </svg>\n          {/* 숫자는 눈으로만 보는 장식이다. 읽어 줄 값은 이미 위 aria-label에 들어 있다. */}\n          <span className=\"hd-dot\" aria-hidden=\"true\">\n            3\n          </span>\n        </button>\n\n        {user && (\n          <div className=\"hd-menu-wrap\" ref={menuRef}>\n            <button\n              type=\"button\"\n              ref={menuButtonRef}\n              className=\"hd-user\"\n              aria-haspopup=\"menu\"\n              aria-expanded={menuOpen}\n              aria-controls={menuId}\n              onClick={() => setMenuOpen((open) => !open)}\n            >\n              <span className=\"hd-avatar\" aria-hidden=\"true\">\n                {user.name.charAt(0)}\n              </span>\n              <span className=\"hd-user-text\">\n                <span className=\"hd-user-name\">{user.name}</span>\n                <span className=\"hd-user-role\">{user.role}</span>\n              </span>\n            </button>\n\n            {/*\n              닫힌 메뉴는 아예 그리지 않는다. hidden으로 남겨 두면 초점 순서에서는 빠지지만\n              메뉴 항목 수가 보조기기에 계속 노출된다.\n            */}\n            {menuOpen && (\n              <div className=\"hd-menu\" id={menuId} role=\"menu\">\n                <button type=\"button\" role=\"menuitem\" className=\"hd-menu-item\" onClick={() => closeMenu(true)}>\n                  내 정보\n                </button>\n                <button type=\"button\" role=\"menuitem\" className=\"hd-menu-item\" onClick={() => closeMenu(true)}>\n                  환경 설정\n                </button>\n                <button\n                  type=\"button\"\n                  role=\"menuitem\"\n                  className=\"hd-menu-item is-danger\"\n                  onClick={() => {\n                    closeMenu(false);\n                    onSignOut?.();\n                  }}\n                >\n                  로그아웃\n                </button>\n              </div>\n            )}\n          </div>\n        )}\n      </div>\n    </header>\n  );\n}\n",
  "header.css": "/* 외부 UI 라이브러리 없이 쓰는 Header 스타일. 폐쇄망에서도 이 파일만 복사하면 된다. */\n.hd {\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  gap: 14px;\n  height: 56px;\n  padding: 0 14px;\n  border-bottom: 1px solid #e2e8f0;\n  background: #fff;\n  color: #0f172a;\n  font-family: inherit;\n}\n.hd.is-dense { height: 46px; gap: 10px; padding: 0 10px; }\n\n/* 스크롤 컨테이너 안에서 위에 붙는다. z-index가 없으면 본문 그림자에 파묻힌다. */\n.hd.is-sticky {\n  position: sticky;\n  top: 0;\n  z-index: 30;\n  box-shadow: 0 1px 0 rgba(15, 23, 42, 0.06), 0 6px 16px rgba(15, 23, 42, 0.06);\n}\n\n/* 눈에서만 빼고 이름은 남기는 표준 방식. display:none이면 label 역할까지 사라진다. */\n.hd-sr-only {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  clip-path: inset(50%);\n}\n\n/* 건너뛰기 링크. 평소엔 화면 위로 밀어 두고 초점을 받으면 내려온다.\n   display:none으로 숨기면 초점을 받을 수 없어 장치 자체가 무의미해진다. */\n.hd-skip {\n  position: absolute;\n  left: 12px;\n  top: 8px;\n  z-index: 40;\n  padding: 8px 12px;\n  border-radius: 8px;\n  background: #2563eb;\n  color: #fff;\n  font-size: 13px;\n  font-weight: 800;\n  text-decoration: none;\n  transform: translateY(-160%);\n  transition: transform 0.15s ease;\n}\n.hd-skip:focus-visible {\n  transform: translateY(0);\n  outline: 2px solid #0f172a;\n  outline-offset: 2px;\n}\n\n.hd-brand {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 8px;\n  color: inherit;\n  font-size: 14px;\n  font-weight: 900;\n  text-decoration: none;\n  white-space: nowrap;\n}\n.hd-mark {\n  display: grid;\n  place-items: center;\n  width: 20px;\n  height: 20px;\n  color: #0f172a;\n}\n.hd-mark svg { width: 19px; height: 19px; }\n.hd.is-dense .hd-mark { width: 18px; height: 18px; }\n\n.hd-nav { min-width: 0; }\n.hd-list {\n  display: flex;\n  gap: 2px;\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n.hd-link {\n  display: block;\n  padding: 7px 11px;\n  border-radius: 8px;\n  color: #475569;\n  font-size: 13px;\n  font-weight: 700;\n  text-decoration: none;\n  white-space: nowrap;\n}\n.hd-link:hover { color: #0f172a; }\n.hd.is-dense .hd-link { padding: 5px 9px; font-size: 12px; }\n\n/* 현재 페이지는 aria-current=\"page\"가 진실이고, 표시는 그 속성을 따라간다.\n   배경을 칠하는 대신 밑줄 하나로 끝낸다. 항목이 6개를 넘으면 색 덩어리가 줄줄이 늘어서기 때문이다. */\n.hd-link[aria-current='page'] {\n  color: #0f172a;\n  font-weight: 800;\n  box-shadow: inset 0 -1.5px 0 #0f172a;\n  border-radius: 0;\n}\n\n/* 검색은 남는 자리를 가져가되, 좁아지면 먼저 줄어든다. */\n.hd-search {\n  position: relative;\n  display: flex;\n  flex: 1 1 200px;\n  min-width: 120px;\n  max-width: 380px;\n  align-items: center;\n}\n.hd-search-icon {\n  position: absolute;\n  left: 9px;\n  display: grid;\n  place-items: center;\n  color: #94a3b8;\n  pointer-events: none;\n}\n.hd-search-icon svg { width: 15px; height: 15px; }\n\n.hd-input {\n  box-sizing: border-box;\n  width: 100%;\n  height: 34px;\n  padding: 0 10px 0 30px;\n  border: 1px solid #e2e8f0;\n  border-radius: 8px;\n  background: #fff;\n  color: inherit;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 600;\n}\n.hd-input::placeholder { color: #94a3b8; font-weight: 600; }\n.hd-input:focus-visible {\n  outline: 2px solid #2563eb;\n  outline-offset: -1px;\n}\n.hd.is-dense .hd-input { height: 29px; font-size: 12px; }\n\n/* 검색이 없으면 액션이 오른쪽 끝에 붙어야 하므로 여기서 남는 자리를 밀어낸다. */\n.hd-actions {\n  display: flex;\n  flex: 0 0 auto;\n  align-items: center;\n  gap: 6px;\n  margin-left: auto;\n}\n\n.hd-icon-button {\n  position: relative;\n  display: grid;\n  place-items: center;\n  width: 34px;\n  height: 34px;\n  border: 1px solid transparent;\n  border-radius: 9px;\n  background: transparent;\n  color: #475569;\n  cursor: pointer;\n}\n.hd-icon-button svg { width: 18px; height: 18px; }\n.hd-icon-button:hover { background: #f1f5f9; color: #0f172a; }\n\n.hd-dot {\n  position: absolute;\n  top: 3px;\n  right: 3px;\n  min-width: 13px;\n  padding: 0 2px;\n  border-radius: 999px;\n  background: #ef4444;\n  color: #fff;\n  font-size: 9px;\n  font-weight: 800;\n  line-height: 13px;\n}\n\n.hd-menu-wrap { position: relative; }\n\n.hd-user {\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 3px 6px 3px 3px;\n  border: 0;\n  border-radius: 9px;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  cursor: pointer;\n}\n.hd-user:hover { background: #f8fafc; }\n.hd-avatar {\n  display: grid;\n  place-items: center;\n  width: 26px;\n  height: 26px;\n  border-radius: 999px;\n  background: #e2e8f0;\n  color: #0f172a;\n  font-size: 11.5px;\n  font-weight: 800;\n}\n.hd-user-text { display: grid; gap: 1px; text-align: left; }\n.hd-user-name { font-size: 12px; font-weight: 800; line-height: 1.1; }\n.hd-user-role { color: #64748b; font-size: 10px; font-weight: 700; line-height: 1.1; }\n/* 좁아지면 이름은 아바타만 남기고 접는다. 이름은 버튼의 title이 아니라 안의 텍스트가 쥐고 있다. */\n.hd.is-dense .hd-user-text { display: none; }\n\n.hd-menu {\n  position: absolute;\n  top: calc(100% + 6px);\n  right: 0;\n  z-index: 40;\n  display: grid;\n  min-width: 168px;\n  padding: 5px;\n  border: 1px solid #e2e8f0;\n  border-radius: 10px;\n  background: #fff;\n  box-shadow: 0 14px 30px rgba(15, 23, 42, 0.16);\n}\n.hd-menu-item {\n  padding: 8px 10px;\n  border: 0;\n  border-radius: 7px;\n  background: transparent;\n  color: #0f172a;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 700;\n  text-align: left;\n  cursor: pointer;\n}\n.hd-menu-item:hover { background: #f1f5f9; }\n.hd-menu-item.is-danger { color: #dc2626; }\n.hd-menu-item.is-danger:hover { background: #fef2f2; }\n\n/* 초점 표시는 마지막에 한 번만 정의해 어떤 요소든 같은 모양으로 보이게 한다. */\n.hd a:focus-visible,\n.hd button:focus-visible {\n  outline: 2px solid #2563eb;\n  outline-offset: 1px;\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .hd-skip { transition: none; }\n}\n",
  "header-demo.tsx": "import { useState } from 'react';\nimport { Header, type HeaderNavItem } from './header';\nimport './header.css';\n\nconst NAV: HeaderNavItem[] = [\n  { id: 'dashboard', label: '대시보드', href: '/dashboard' },\n  { id: 'lot', label: 'LOT 조회', href: '/production/lot' },\n  { id: 'quality', label: '품질', href: '/quality' },\n  { id: 'equipment', label: '설비', href: '/equipment' },\n];\n\n/**\n * 갤러리 전용 시연 래퍼.\n * sticky는 스크롤이 있어야 확인되므로, 헤더를 스크롤 컨테이너 안에 넣고 본문을 길게 둔다.\n * 실제 앱에서는 activeId를 라우터에서 읽고 onSelect 대신 <Link>를 쓴다.\n */\nexport function HeaderDemo({\n  sticky = true,\n  dense = false,\n  search = true,\n}: {\n  sticky?: boolean;\n  dense?: boolean;\n  search?: boolean;\n}) {\n  const [activeId, setActiveId] = useState('lot');\n\n  return (\n    <div\n      style={{\n        // 미리보기 자리가 place-items:center라 폭을 주지 않으면 내용만큼 줄어든다.\n        width: '100%',\n        height: 300,\n        overflow: 'auto',\n        background: '#f8fafc',\n        border: '1px solid #e2e8f0',\n        borderRadius: 10,\n      }}\n    >\n      <Header\n        brand=\"PKT MES\"\n        items={NAV}\n        activeId={activeId}\n        onSelect={setActiveId}\n        sticky={sticky}\n        dense={dense}\n        search={search}\n        user={{ name: '오현석', role: '공정 관리자' }}\n        label=\"상단 메뉴\"\n        mainId=\"hd-demo-main\"\n      />\n\n      {/* 건너뛰기 링크가 가리키는 곳. tabIndex가 없으면 초점이 실제로 옮겨지지 않는 브라우저가 있다. */}\n      <main id=\"hd-demo-main\" tabIndex={-1} style={{ padding: 16, color: '#475569', fontSize: 13, fontWeight: 700 }}>\n        선택된 항목: <code style={{ color: '#2563eb' }}>{activeId}</code>\n        <p style={{ marginTop: 10, fontWeight: 600, lineHeight: 1.7 }}>\n          이 상자 안을 스크롤해 보세요. 고정을 켜면 헤더가 위에 붙습니다.\n          <br />\n          Tab을 처음 누르면 \"본문으로 건너뛰기\"가 먼저 나타납니다. 메뉴를 매번 훑지 않게 하는 장치입니다.\n          <br />\n          프로필을 열고 Esc를 누르면 초점이 버튼으로 되돌아옵니다.\n        </p>\n        {Array.from({ length: 8 }, (_, index) => (\n          <p key={index} style={{ marginTop: 10, fontWeight: 600, color: '#94a3b8' }}>\n            LOT-2408{index + 10} · 노광 공정 · 진행 중\n          </p>\n        ))}\n      </main>\n    </div>\n  );\n}\n",
  "input.tsx": "import type { InputHTMLAttributes } from 'react';\nimport './input.css';\n\ntype InputSize = 'sm' | 'md' | 'lg';\n\ntype InputProps = Omit<InputHTMLAttributes<HTMLInputElement>, 'size'> & {\n  label?: string;\n  size?: InputSize;\n  invalid?: boolean;\n  /** invalid일 때만 보여주는 오류 문구. */\n  error?: string;\n  hint?: string;\n};\n\nexport function Input({\n  label,\n  size = 'md',\n  invalid = false,\n  error,\n  hint,\n  className = '',\n  ...props\n}: InputProps) {\n  return (\n    <label className={`field field-${size} ${invalid ? 'field-invalid' : ''} ${className}`}>\n      {label ? <span className=\"field-label\">{label}</span> : null}\n      <input className=\"field-input\" aria-invalid={invalid || undefined} {...props} />\n      {invalid && error ? <span className=\"field-error\">{error}</span> : hint ? <span className=\"field-hint\">{hint}</span> : null}\n    </label>\n  );\n}\n",
  "input.css": "/* 외부 UI 라이브러리 없이 쓰는 Input 스타일. */\n.field { display: inline-flex; flex-direction: column; gap: 6px; min-width: 240px; }\n.field-label { font-size: 12px; font-weight: 800; color: #334155; }\n.field-input {\n  width: 100%;\n  border: 1px solid #cbd5e1;\n  border-radius: 8px;\n  background: #fff;\n  color: #0f172a;\n  font-family: inherit;\n  outline: none;\n  transition: border-color 0.15s ease, box-shadow 0.15s ease;\n}\n.field-input::placeholder { color: #94a3b8; }\n.field-input:focus { border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }\n.field-input:disabled { background: #f1f5f9; color: #94a3b8; cursor: not-allowed; }\n\n.field-sm .field-input { padding: 7px 10px; font-size: 12px; }\n.field-md .field-input { padding: 9px 12px; font-size: 13px; }\n.field-lg .field-input { padding: 12px 14px; font-size: 15px; }\n\n.field-invalid .field-input { border-color: #dc2626; }\n.field-invalid .field-input:focus { box-shadow: 0 0 0 3px rgba(220, 38, 38, 0.18); }\n.field-error { font-size: 12px; font-weight: 700; color: #dc2626; }\n.field-hint { font-size: 12px; font-weight: 600; color: #64748b; }\n",
  "modal.tsx": "import type { ReactNode } from 'react';\nimport './modal.css';\n\ntype SheetKind = 'modal' | 'drawer';\ntype DrawerSide = 'left' | 'right';\n\ntype ModalProps = {\n  open: boolean;\n  kind?: SheetKind;\n  /** drawer일 때만 쓰인다. */\n  side?: DrawerSide;\n  title: string;\n  description?: string;\n  children?: ReactNode;\n  footer?: ReactNode;\n  onClose?: () => void;\n};\n\n/**\n * 포털을 쓰지 않는다. 부모 안에 absolute로 깔리므로 미리보기 안에 가둘 수 있고,\n * 화면 전체를 덮어야 하면 사용하는 쪽에서 fixed 컨테이너에 넣거나 createPortal로 감싼다.\n */\nexport function Modal({\n  open,\n  kind = 'modal',\n  side = 'right',\n  title,\n  description,\n  children,\n  footer,\n  onClose,\n}: ModalProps) {\n  if (!open) return null;\n\n  const place = kind === 'modal' ? 'overlay-center' : side === 'left' ? 'overlay-left' : 'overlay-right';\n\n  return (\n    <div className={`overlay ${place}`} role=\"dialog\" aria-modal=\"true\" aria-label={title}>\n      <div className={`sheet sheet-${kind}`}>\n        <div className=\"sheet-head\">\n          <div className=\"sheet-heads\">\n            <h2 className=\"sheet-title\">{title}</h2>\n            {description ? <p className=\"sheet-desc\">{description}</p> : null}\n          </div>\n          <button type=\"button\" className=\"sheet-close\" onClick={onClose} aria-label=\"닫기\">×</button>\n        </div>\n        <div className=\"sheet-body\">{children}</div>\n        {footer ? <div className=\"sheet-foot\">{footer}</div> : null}\n      </div>\n    </div>\n  );\n}\n",
  "modal.css": "/* 외부 UI 라이브러리 없이 쓰는 Modal·Drawer 스타일.\n   포털을 쓰지 않고 부모 안에 absolute로 깔리므로, 화면 전체를 덮으려면\n   position:fixed 컨테이너에 넣거나 사용하는 쪽에서 createPortal로 감싼다. */\n.overlay {\n  position: absolute;\n  inset: 0;\n  background: rgba(15, 23, 42, 0.45);\n  display: flex;\n  z-index: 10;\n}\n.overlay-center { align-items: center; justify-content: center; padding: 20px; }\n.overlay-right  { align-items: stretch; justify-content: flex-end; }\n.overlay-left   { align-items: stretch; justify-content: flex-start; }\n\n.sheet {\n  background: #fff;\n  display: flex;\n  flex-direction: column;\n  box-shadow: 0 18px 44px rgba(15, 23, 42, 0.24);\n  font-family: inherit;\n  min-width: 0;\n}\n.sheet-modal  { width: min(440px, 100%); border-radius: 14px; max-height: 100%; }\n.sheet-drawer { width: min(320px, 84%); height: 100%; }\n\n.sheet-head {\n  display: flex; align-items: flex-start; gap: 12px;\n  padding: 16px 18px 12px;\n  border-bottom: 1px solid #e2e8f0;\n}\n.sheet-heads { min-width: 0; }\n.sheet-title { font-size: 15px; font-weight: 900; color: #0f172a; margin: 0; }\n.sheet-desc  { font-size: 12.5px; font-weight: 600; color: #64748b; margin: 4px 0 0; }\n.sheet-close {\n  margin-left: auto; flex-shrink: 0;\n  width: 28px; height: 28px;\n  display: grid; place-items: center;\n  border: 0; border-radius: 7px;\n  background: transparent; color: #475569;\n  font-size: 16px; line-height: 1; cursor: pointer;\n}\n.sheet-close:hover { background: #f1f5f9; }\n\n.sheet-body { padding: 16px 18px; font-size: 13px; font-weight: 600; color: #334155; overflow-y: auto; }\n.sheet-foot {\n  display: flex; justify-content: flex-end; gap: 8px;\n  padding: 12px 18px 16px;\n  border-top: 1px solid #e2e8f0;\n  margin-top: auto;\n}\n",
  "modal-demo.tsx": "import { useEffect, useState } from 'react';\nimport { Button } from './button';\nimport { Modal } from './modal';\nimport './modal.css';\n\n/**\n * 갤러리 전용 시연 래퍼.\n * Modal이 부모 기준 absolute로 깔리므로 무대에 position:relative를 준다.\n */\nexport function ModalDemo({\n  kind = 'modal',\n  side = 'right',\n  open: openProp = true,\n  title = 'LOT 삭제',\n  description = '되돌릴 수 없습니다.',\n}: {\n  kind?: 'modal' | 'drawer';\n  side?: 'left' | 'right';\n  open?: boolean;\n  title?: string;\n  description?: string;\n}) {\n  const [open, setOpen] = useState(openProp);\n\n  // 컨트롤에서 open을 바꾸면 따라가되, 그 뒤에는 버튼으로 다시 열고 닫을 수 있다.\n  useEffect(() => setOpen(openProp), [openProp]);\n\n  return (\n    <div style={{ position: 'relative', width: '100%', minHeight: 300, background: '#f8fafc', borderRadius: 10, overflow: 'hidden' }}>\n      <div style={{ padding: 20 }}>\n        <Button variant=\"danger\" onClick={() => setOpen(true)}>LOT 삭제</Button>\n      </div>\n      <Modal\n        open={open}\n        kind={kind}\n        side={side}\n        title={title}\n        description={description}\n        onClose={() => setOpen(false)}\n        footer={\n          <>\n            <Button variant=\"ghost\" size=\"sm\" onClick={() => setOpen(false)}>취소</Button>\n            <Button variant=\"danger\" size=\"sm\" onClick={() => setOpen(false)}>삭제</Button>\n          </>\n        }\n      >\n        LOT-24084를 삭제하면 연결된 공정 이력도 함께 사라집니다. 계속할까요?\n      </Modal>\n    </div>\n  );\n}\n",
  "select.tsx": "import type { SelectHTMLAttributes } from 'react';\nimport './select.css';\n\ntype SelectSize = 'sm' | 'md' | 'lg';\n\ntype SelectProps = Omit<SelectHTMLAttributes<HTMLSelectElement>, 'size' | 'children'> & {\n  label?: string;\n  size?: SelectSize;\n  options: string[];\n  placeholder?: string;\n};\n\nexport function Select({ label, size = 'md', options, placeholder, className = '', ...props }: SelectProps) {\n  return (\n    <label className={`picker picker-${size} ${className}`}>\n      {label ? <span className=\"picker-label\">{label}</span> : null}\n      <select className=\"picker-control\" defaultValue={placeholder ? '' : undefined} {...props}>\n        {placeholder ? <option value=\"\" disabled>{placeholder}</option> : null}\n        {options.map((option) => (\n          <option key={option} value={option}>{option}</option>\n        ))}\n      </select>\n    </label>\n  );\n}\n",
  "select.css": "/* 외부 UI 라이브러리 없이 쓰는 Select 스타일. */\n.picker { display: inline-flex; flex-direction: column; gap: 6px; min-width: 240px; }\n.picker-label { font-size: 12px; font-weight: 800; color: #334155; }\n.picker-control {\n  width: 100%;\n  appearance: none;\n  border: 1px solid #cbd5e1;\n  border-radius: 8px;\n  background: #fff;\n  color: #0f172a;\n  font-family: inherit;\n  outline: none;\n  /* 화살표를 배경 이미지 대신 그라디언트로 그려 외부 asset 의존을 없앤다. */\n  background-image:\n    linear-gradient(45deg, transparent 50%, #64748b 50%),\n    linear-gradient(135deg, #64748b 50%, transparent 50%);\n  background-position: right 16px center, right 11px center;\n  background-size: 5px 5px, 5px 5px;\n  background-repeat: no-repeat;\n}\n.picker-control:focus { border-color: #2563eb; box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.18); }\n.picker-control:disabled { background-color: #f1f5f9; color: #94a3b8; cursor: not-allowed; }\n\n.picker-sm .picker-control { padding: 7px 30px 7px 10px; font-size: 12px; }\n.picker-md .picker-control { padding: 9px 32px 9px 12px; font-size: 13px; }\n.picker-lg .picker-control { padding: 12px 34px 12px 14px; font-size: 15px; }\n",
  "sidebar.tsx": "import { useEffect, useId, useRef, useState, type KeyboardEvent, type ReactNode, type TransitionEvent } from 'react';\nimport './sidebar.css';\n\nexport type SidebarItem = {\n  id: string;\n  label: string;\n  /** 라우터를 쓰면 실제 경로를 넣는다. 없으면 '#'로 떨어진다. */\n  href?: string;\n  icon?: ReactNode;\n  badge?: string | number;\n  children?: SidebarItem[];\n};\n\ntype SidebarProps = {\n  items: SidebarItem[];\n  /** 현재 페이지. 보통 라우터가 쥐고 있으므로 밖에서 받는다. */\n  activeId: string;\n  onSelect: (id: string) => void;\n  collapsed?: boolean;\n  dense?: boolean;\n  /** nav 랜드마크의 이름. 한 화면에 nav가 둘 이상이면 서로 다르게 준다. */\n  label?: string;\n};\n\n/**\n * 하위 목록의 여닫힘.\n * display:none은 높이가 트랜지션되지 않으므로, 닫히는 동안에는 hidden을 붙이지 않고\n * 애니메이션이 끝난 뒤에 붙인다. 보조기기에서 사라지는 시점만 0.2초 뒤로 밀리는 셈이다.\n * 접힘(flyout)에서는 밀어낼 자리가 없으므로 높이 대신 페이드로 여닫는다.\n */\nfunction SubMenu({\n  id,\n  open,\n  collapsed,\n  children,\n}: {\n  id: string;\n  open: boolean;\n  collapsed: boolean;\n  children: ReactNode;\n}) {\n  const clipRef = useRef<HTMLDivElement>(null);\n  const listRef = useRef<HTMLUListElement>(null);\n  const [hidden, setHidden] = useState(!open);\n\n  useEffect(() => {\n    const clip = clipRef.current;\n    const list = listRef.current;\n    if (!clip || !list) return;\n    if (collapsed) return; // flyout은 높이를 건드리지 않는다.\n    if (open) {\n      // display:none인 동안에는 높이를 잴 수 없다. 먼저 보이게 한 뒤 다음 렌더에서 잡는다.\n      if (hidden) {\n        setHidden(false);\n        return;\n      }\n      clip.style.height = `${list.offsetHeight}px`;\n      return;\n    }\n    // auto에서 0으로는 트랜지션이 걸리지 않으니, 지금 높이를 픽셀로 굳힌 뒤 0으로 보낸다.\n    clip.style.height = `${clip.offsetHeight}px`;\n    const raf = requestAnimationFrame(() => {\n      clip.style.height = '0px';\n    });\n    return () => cancelAnimationFrame(raf);\n  }, [open, hidden, collapsed]);\n\n  useEffect(() => {\n    if (open) setHidden(false);\n  }, [open]);\n\n  const handleTransitionEnd = (event: TransitionEvent<HTMLDivElement>) => {\n    if (event.target !== event.currentTarget) return;\n    if (!open) {\n      setHidden(true);\n      return;\n    }\n    // 열린 뒤에는 auto로 돌려 둔다. dense를 켜거나 항목이 바뀌어도 높이가 어긋나지 않는다.\n    if (event.propertyName === 'height' && clipRef.current) clipRef.current.style.height = 'auto';\n  };\n\n  return (\n    <div\n      ref={clipRef}\n      id={id}\n      hidden={hidden}\n      onTransitionEnd={handleTransitionEnd}\n      className={`sb-sub-clip${open ? ' is-open' : ''}`}\n      style={{ height: collapsed ? undefined : 0 }}\n    >\n      <ul ref={listRef} className=\"sb-sub\">\n        {children}\n      </ul>\n    </div>\n  );\n}\n\n/**\n * 골격 요약\n * - 바깥은 <nav aria-label>. 랜드마크가 있어야 스크린리더가 \"메뉴로 건너뛰기\"를 할 수 있다.\n * - 목록은 <ul>/<li>. 항목이 몇 개인지 읽어 주는 것은 이 구조뿐이다.\n * - 이동하는 항목은 <a>, 펼치기만 하는 항목은 <button>. 역할이 다르면 태그도 달라야 한다.\n * - 현재 페이지는 aria-current=\"page\". 색만 칠하면 눈으로만 보이는 상태가 된다.\n * - 펼치기 버튼은 aria-expanded + aria-controls로 어느 목록을 여는지 가리킨다.\n */\nexport function Sidebar({\n  items,\n  activeId,\n  onSelect,\n  collapsed = false,\n  dense = false,\n  label = '주 메뉴',\n}: SidebarProps) {\n  // 펼침은 순수 UI 상태라 안에서 갖는다. 활성 항목과 달리 주소에 남을 이유가 없다.\n  // 활성 자식을 품은 그룹만 열어 두되, 접힘일 때는 flyout이 저절로 떠 버리므로 모두 닫는다.\n  const autoOpen = () =>\n    collapsed\n      ? []\n      : items.filter((item) => item.children?.some((child) => child.id === activeId)).map((item) => item.id);\n\n  const [openIds, setOpenIds] = useState<string[]>(autoOpen);\n\n  // 접기/펴기를 오갈 때마다 펼침 상태를 그 모드의 기본값으로 되돌린다.\n  useEffect(() => {\n    setOpenIds(autoOpen());\n    // autoOpen은 collapsed에만 반응하면 된다. 목록이 바뀌면 어차피 다시 마운트된다.\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [collapsed]);\n\n  // 한 화면에 Sidebar가 둘 이상 있어도 aria-controls가 엉키지 않도록 인스턴스마다 접두사를 붙인다.\n  const uid = useId();\n\n  const toggleGroup = (id: string) =>\n    setOpenIds((prev) => {\n      if (prev.includes(id)) return prev.filter((openId) => openId !== id);\n      // 펼친 상태의 하위 목록은 아래로 밀고 들어가므로 여러 개가 동시에 열려도 된다.\n      // 접힘에서는 같은 자리에 떠올라 서로 겹치므로 한 번에 하나만 연다.\n      return collapsed ? [id] : [...prev, id];\n    });\n\n  // 떠 있는 하위 메뉴는 Esc로 닫힌다. 펼친 상태에서는 닫을 것이 없다.\n  const handleKeyDown = (event: KeyboardEvent<HTMLElement>) => {\n    if (collapsed && event.key === 'Escape') setOpenIds([]);\n  };\n\n  const renderLink = (item: SidebarItem) => (\n    <a\n      className=\"sb-row\"\n      href={item.href ?? '#'}\n      // 색이 아니라 이 속성이 \"현재 페이지\"의 진짜 표시다.\n      aria-current={item.id === activeId ? 'page' : undefined}\n      // 접히면 라벨이 눈에서 사라지므로 마우스 사용자에게는 툴팁으로 준다.\n      title={collapsed ? item.label : undefined}\n      onClick={(event) => {\n        // 라우터를 붙이면 이 줄을 지우고 <Link>로 바꾼다.\n        event.preventDefault();\n        onSelect(item.id);\n        // 떠 있는 하위 메뉴는 항목을 고르면 닫는다. 펼친 상태에서는 열어 둔다.\n        if (collapsed) setOpenIds([]);\n      }}\n    >\n      <span className=\"sb-icon\" aria-hidden=\"true\">\n        {item.icon}\n      </span>\n      <span className=\"sb-label\">{item.label}</span>\n      {item.badge != null ? <span className=\"sb-badge\">{item.badge}</span> : null}\n    </a>\n  );\n\n  const renderGroup = (item: SidebarItem) => {\n    const open = openIds.includes(item.id);\n    const hasActiveChild = item.children?.some((child) => child.id === activeId) ?? false;\n    const subId = `sb-sub-${uid}-${item.id}`;\n\n    return (\n      <>\n        <button\n          type=\"button\"\n          className={`sb-row${hasActiveChild ? ' is-parent-active' : ''}`}\n          aria-expanded={open}\n          aria-controls={subId}\n          title={collapsed ? item.label : undefined}\n          onClick={() => toggleGroup(item.id)}\n        >\n          <span className=\"sb-icon\" aria-hidden=\"true\">\n            {item.icon}\n          </span>\n          <span className=\"sb-label\">{item.label}</span>\n          <span className=\"sb-caret\" aria-hidden=\"true\" />\n        </button>\n        {/*\n          닫힌 목록은 결국 hidden 속성으로 숨는다. display:none으로만 숨기고 hidden을 빼면\n          화면에서만 사라지고 보조기기에는 남는다. 반대로 [hidden]을 CSS로 되살리는 것도 같은 이유로 금물.\n          접힘일 때는 이 목록이 항목 오른쪽에 떠오르는 flyout이 될 뿐, 여닫는 조건은 똑같다.\n        */}\n        <SubMenu id={subId} open={open} collapsed={collapsed}>\n          {item.children?.map((child) => (\n            <li key={child.id} className=\"sb-item\">\n              {renderLink(child)}\n            </li>\n          ))}\n        </SubMenu>\n      </>\n    );\n  };\n\n  return (\n    <nav\n      className={`sb${collapsed ? ' is-collapsed' : ''}${dense ? ' is-dense' : ''}`}\n      aria-label={label}\n      onKeyDown={handleKeyDown}\n    >\n      <ul className=\"sb-list\">\n        {items.map((item) => (\n          <li key={item.id} className=\"sb-item\">\n            {item.children?.length ? renderGroup(item) : renderLink(item)}\n          </li>\n        ))}\n      </ul>\n    </nav>\n  );\n}\n",
  "sidebar.css": "/* 외부 UI 라이브러리 없이 쓰는 Sidebar 스타일. 폐쇄망에서도 이 파일만 복사하면 된다. */\n.sb {\n  box-sizing: border-box;\n  width: 232px;\n  /* 떠오르는 하위 메뉴가 레일 바깥까지 나가려면 이 여백만큼을 더 밀어야 한다. */\n  --sb-pad-x: 8px;\n  padding: 10px var(--sb-pad-x);\n  background: #0f172a;\n  color: #cbd5e1;\n  font-family: inherit;\n  transition: width 0.18s ease;\n}\n.sb.is-collapsed { width: 60px; }\n\n.sb-list,\n.sb-sub {\n  margin: 0;\n  padding: 0;\n  list-style: none;\n}\n\n/* 접힌 상태의 하위 메뉴가 이 항목 기준으로 떠야 하므로 위치 기준을 잡아 둔다. */\n.sb-item { position: relative; }\n.sb-item + .sb-item { margin-top: 2px; }\n\n/* a와 button 두 종류가 같은 줄로 보여야 하므로 모양을 여기서 한 번에 맞춘다. */\n.sb-row {\n  box-sizing: border-box;\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  width: 100%;\n  padding: 9px 10px;\n  border: 0;\n  border-radius: 8px;\n  background: transparent;\n  color: inherit;\n  font: inherit;\n  font-size: 13px;\n  font-weight: 700;\n  text-align: left;\n  text-decoration: none;\n  cursor: pointer;\n}\n.sb-row:hover { background: #1e293b; color: #f8fafc; }\n.sb-row:focus-visible {\n  outline: 2px solid #60a5fa;\n  outline-offset: -2px;\n}\n\n.sb.is-dense .sb-row { padding: 6px 10px; font-size: 12px; }\n\n/* 현재 페이지는 aria-current=\"page\"가 진실이고, 색은 그 속성을 따라간다. */\n.sb-row[aria-current='page'] {\n  background: #2563eb;\n  color: #fff;\n}\n/* 자식이 현재 페이지인 그룹.\n   접으면 자식 줄이 통째로 사라지므로, 이 표시가 \"지금 어디에 있나\"의 유일한 단서가 된다. */\n.sb-row.is-parent-active {\n  background: #1e293b;\n  color: #f8fafc;\n}\n.sb-row.is-parent-active .sb-icon { color: #60a5fa; }\n/* 접힘에서는 라벨도 없으므로 왼쪽 띠를 하나 더 준다. */\n.sb.is-collapsed .sb-row.is-parent-active { box-shadow: inset 2px 0 0 #60a5fa; }\n\n.sb-icon {\n  display: grid;\n  place-items: center;\n  flex: 0 0 18px;\n  width: 18px;\n  height: 18px;\n}\n.sb-icon svg { display: block; width: 16px; height: 16px; }\n\n.sb-label {\n  flex: 1 1 auto;\n  overflow: hidden;\n  white-space: nowrap;\n  text-overflow: ellipsis;\n}\n\n.sb-badge {\n  flex: 0 0 auto;\n  padding: 2px 7px;\n  border-radius: 999px;\n  background: #334155;\n  color: #e2e8f0;\n  font-size: 11px;\n  font-weight: 800;\n}\n.sb-row[aria-current='page'] .sb-badge { background: rgba(255, 255, 255, 0.25); color: #fff; }\n\n.sb-caret {\n  flex: 0 0 auto;\n  width: 0;\n  height: 0;\n  border-top: 4px solid currentColor;\n  border-right: 4px solid transparent;\n  border-left: 4px solid transparent;\n  transition: transform 0.15s ease;\n}\n.sb-row[aria-expanded='true'] .sb-caret { transform: rotate(180deg); }\n\n/* 여닫힘을 담당하는 겉껍데기. 높이를 잘라 내는 쪽과 내용을 그리는 쪽을 나눠야\n   하위 목록의 여백·테두리가 애니메이션 도중에 찌그러지지 않는다. */\n.sb-sub-clip {\n  overflow: hidden;\n  transition: height 0.18s ease;\n}\n\n/* 펼친 상태의 하위 메뉴는 들여쓰기로 계층을 보여준다. */\n.sb-sub {\n  margin: 2px 0 2px 17px;\n  padding-left: 9px;\n  border-left: 1px solid #334155;\n}\n.sb-sub .sb-row { font-weight: 600; }\n\n.sb-group-label {\n  margin: 12px 10px 4px;\n  color: #64748b;\n  font-size: 10px;\n  font-weight: 800;\n  letter-spacing: 0.1em;\n  text-transform: uppercase;\n}\n\n/* ── 접힘 상태 ───────────────────────────────────────────────\n   라벨을 display:none으로 지우면 접근성 이름까지 사라진다.\n   눈에서만 빼고 이름은 남기려면 이 sr-only 방식을 쓴다. */\n.sb.is-collapsed .sb-label,\n.sb.is-collapsed .sb-badge,\n.sb.is-collapsed .sb-group-label {\n  position: absolute;\n  width: 1px;\n  height: 1px;\n  margin: -1px;\n  padding: 0;\n  overflow: hidden;\n  white-space: nowrap;\n  clip-path: inset(50%);\n}\n.sb.is-collapsed .sb-row { justify-content: center; padding: 9px 0; }\n.sb.is-collapsed .sb-sub .sb-row { justify-content: flex-start; padding: 8px 10px; }\n.sb.is-collapsed .sb-caret { display: none; }\n\n/* 접힘의 flyout은 높이를 줄일 자리가 없다. 대신 살짝 밀려 들어오며 나타난다.\n   overflow는 풀어야 떠 있는 목록과 그림자가 잘리지 않는다. */\n.sb.is-collapsed .sb-sub-clip {\n  overflow: visible;\n  opacity: 0;\n  transform: translateX(-4px);\n  transition: opacity 0.14s ease, transform 0.14s ease;\n}\n.sb.is-collapsed .sb-sub-clip.is-open {\n  opacity: 1;\n  transform: none;\n}\n\n/* 접히면 하위 메뉴를 들여쓸 자리가 없으므로 항목 오른쪽으로 띄운다.\n   기준은 레일이 아니라 항목(li)이라, 레일의 좌우 여백을 더해야 레일 바깥으로 나간다. */\n.sb.is-collapsed .sb-sub {\n  position: absolute;\n  top: 0;\n  left: calc(100% + var(--sb-pad-x) + 4px);\n  z-index: 20;\n  min-width: 176px;\n  margin: 0;\n  padding: 6px;\n  border: 1px solid #334155;\n  border-radius: 10px;\n  background: #0f172a;\n  box-shadow: 0 12px 28px rgba(15, 23, 42, 0.45);\n}\n/* flyout 안에서는 자리가 있으므로 라벨과 배지를 도로 보여 준다. */\n.sb.is-collapsed .sb-sub .sb-label,\n.sb.is-collapsed .sb-sub .sb-badge {\n  position: static;\n  width: auto;\n  height: auto;\n  margin: 0;\n  clip-path: none;\n}\n\n/* 움직임을 줄여 달라고 설정한 사용자에게는 여닫힘을 즉시 처리한다. */\n@media (prefers-reduced-motion: reduce) {\n  .sb,\n  .sb-caret,\n  .sb-sub-clip,\n  .sb.is-collapsed .sb-sub-clip {\n    transition: none;\n  }\n}\n",
  "sidebar-demo.tsx": "import { useState } from 'react';\nimport { Sidebar, type SidebarItem } from './sidebar';\nimport './sidebar.css';\n\n/** 아이콘도 외부 패키지 없이 인라인 SVG로 둔다. 폐쇄망에서 lucide를 못 받기 때문이다. */\nconst icon = (path: string) => (\n  <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"2\" strokeLinecap=\"round\" strokeLinejoin=\"round\">\n    <path d={path} />\n  </svg>\n);\n\nconst MENU: SidebarItem[] = [\n  { id: 'dashboard', label: '대시보드', href: '/dashboard', icon: icon('M4 4h7v7H4zM13 4h7v4h-7zM13 12h7v8h-7zM4 15h7v5H4z') },\n  {\n    id: 'production',\n    label: '생산 관리',\n    icon: icon('M3 20h18M5 20V9l5 3V9l5 3V9l4 3v8'),\n    children: [\n      { id: 'lot', label: 'LOT 조회', href: '/production/lot', badge: 12 },\n      { id: 'work-order', label: '작업 지시', href: '/production/work-order' },\n      { id: 'yield', label: '수율 분석', href: '/production/yield' },\n    ],\n  },\n  {\n    id: 'quality',\n    label: '품질',\n    icon: icon('M12 3l8 4v5c0 4.5-3.2 7.9-8 9-4.8-1.1-8-4.5-8-9V7z'),\n    children: [\n      { id: 'inspection', label: '검사 이력', href: '/quality/inspection' },\n      { id: 'defect', label: '불량 코드', href: '/quality/defect', badge: 3 },\n    ],\n  },\n  { id: 'equipment', label: '설비', href: '/equipment', icon: icon('M7 7h10v10H7zM9 3v4M15 3v4M9 17v4M15 17v4M3 9h4M3 15h4M17 9h4M17 15h4') },\n  { id: 'settings', label: '환경 설정', href: '/settings', icon: icon('M4 6h16M4 12h16M4 18h16M9 4v4M15 10v4M7 16v4') },\n];\n\n/**\n * 갤러리 전용 시연 래퍼.\n * 실제 앱에서는 activeId를 라우터에서 읽고 onSelect 대신 <Link>를 쓴다.\n * 여기서는 라우터가 없으므로 state 하나로 대신한다.\n */\nexport function SidebarDemo({\n  collapsed = false,\n  dense = false,\n  label = '주 메뉴',\n}: {\n  collapsed?: boolean;\n  dense?: boolean;\n  label?: string;\n}) {\n  const [activeId, setActiveId] = useState('lot');\n\n  return (\n    <div style={{ display: 'flex', gap: 16, minHeight: 340, background: '#f8fafc', borderRadius: 10, padding: 12 }}>\n      <Sidebar items={MENU} activeId={activeId} onSelect={setActiveId} collapsed={collapsed} dense={dense} label={label} />\n      <div style={{ flex: 1, padding: '10px 4px', color: '#475569', fontSize: 13, fontWeight: 700 }}>\n        선택된 항목: <code style={{ color: '#2563eb' }}>{activeId}</code>\n        <p style={{ marginTop: 10, fontWeight: 600, lineHeight: 1.7 }}>\n          Tab으로 항목 사이를 이동해 보세요. 그룹은 Enter/Space로 펼칩니다.\n          <br />\n          접힘을 켜면 라벨이 눈에서만 사라지고, 하위 메뉴는 오른쪽에 떠오릅니다.\n        </p>\n      </div>\n    </div>\n  );\n}\n",
  "table.tsx": "import type { ReactNode } from 'react';\nimport './table.css';\n\nexport type Column<Row> = {\n  key: string;\n  header: string;\n  align?: 'left' | 'right';\n  render?: (row: Row) => ReactNode;\n};\n\ntype DataTableProps<Row> = {\n  columns: Column<Row>[];\n  rows: Row[];\n  compact?: boolean;\n  striped?: boolean;\n  hover?: boolean;\n  emptyText?: string;\n};\n\nexport function DataTable<Row extends Record<string, unknown>>({\n  columns,\n  rows,\n  compact = false,\n  striped = true,\n  hover = true,\n  emptyText = '표시할 데이터가 없습니다.',\n}: DataTableProps<Row>) {\n  const size = compact ? 'data-table-compact' : 'data-table-md';\n\n  return (\n    <div className=\"data-table-wrap\">\n      {rows.length === 0 ? (\n        <div className=\"data-table-empty\">{emptyText}</div>\n      ) : (\n        <table className={`data-table ${size} ${striped ? 'data-table-striped' : ''} ${hover ? 'data-table-hover' : ''}`}>\n          <thead>\n            <tr>\n              {columns.map((column) => (\n                <th key={column.key} className={column.align === 'right' ? 'col-right' : undefined}>\n                  {column.header}\n                </th>\n              ))}\n            </tr>\n          </thead>\n          <tbody>\n            {rows.map((row, index) => (\n              <tr key={index}>\n                {columns.map((column) => (\n                  <td key={column.key} className={column.align === 'right' ? 'col-right' : undefined}>\n                    {column.render ? column.render(row) : String(row[column.key] ?? '')}\n                  </td>\n                ))}\n              </tr>\n            ))}\n          </tbody>\n        </table>\n      )}\n    </div>\n  );\n}\n",
  "table.css": "/* 외부 UI 라이브러리 없이 쓰는 Table 스타일. */\n.data-table-wrap { width: 100%; overflow-x: auto; border: 1px solid #e2e8f0; border-radius: 10px; background: #fff; }\n.data-table { width: 100%; border-collapse: collapse; font-family: inherit; }\n.data-table th, .data-table td { text-align: left; border-bottom: 1px solid #e2e8f0; white-space: nowrap; }\n.data-table th { background: #f8fafc; font-size: 12px; font-weight: 900; color: #475569; }\n.data-table td { font-size: 13px; font-weight: 600; color: #0f172a; }\n.data-table tbody tr:last-child td { border-bottom: 0; }\n\n.data-table-md th, .data-table-md td { padding: 11px 14px; }\n.data-table-compact th, .data-table-compact td { padding: 7px 12px; }\n\n.data-table-striped tbody tr:nth-child(even) { background: #f8fafc; }\n.data-table-hover tbody tr:hover { background: #eff6ff; }\n\n.data-table .col-right { text-align: right; }\n.data-table-empty { padding: 28px; text-align: center; font-size: 13px; font-weight: 700; color: #64748b; }\n",
  "table-demo.tsx": "import { Badge } from './badge';\nimport { DataTable, type Column } from './table';\nimport './table.css';\n\ntype Lot = { lot: string; product: string; step: string; qty: number; status: string };\n\nconst SAMPLE: Lot[] = [\n  { lot: 'LOT-24081', product: 'PKT-A100', step: '노광', qty: 1200, status: '진행' },\n  { lot: 'LOT-24082', product: 'PKT-A100', step: '식각', qty: 980, status: '대기' },\n  { lot: 'LOT-24083', product: 'PKT-B220', step: '검사', qty: 1500, status: '완료' },\n  { lot: 'LOT-24084', product: 'PKT-B220', step: '노광', qty: 640, status: '이상' },\n  { lot: 'LOT-24085', product: 'PKT-C310', step: '세정', qty: 2100, status: '진행' },\n];\n\nconst TONE: Record<string, 'neutral' | 'info' | 'success' | 'danger'> = {\n  대기: 'neutral', 진행: 'info', 완료: 'success', 이상: 'danger',\n};\n\nconst COLUMNS: Column<Lot>[] = [\n  { key: 'lot', header: 'LOT' },\n  { key: 'product', header: '제품' },\n  { key: 'step', header: '공정' },\n  { key: 'qty', header: '수량', align: 'right', render: (row) => row.qty.toLocaleString() },\n  { key: 'status', header: '상태', render: (row) => <Badge tone={TONE[row.status] ?? 'neutral'} size=\"sm\" dot>{row.status}</Badge> },\n];\n\n/** 갤러리 전용 시연 래퍼. 실제 재사용 대상은 table.tsx의 DataTable이다. */\nexport function TableDemo({ rowCount = 5, ...props }: { rowCount?: number; compact?: boolean; striped?: boolean; hover?: boolean }) {\n  return <DataTable columns={COLUMNS} rows={SAMPLE.slice(0, rowCount)} {...props} />;\n}\n",
  "toggle.tsx": "import './toggle.css';\n\ntype ToggleKind = 'checkbox' | 'radio' | 'switch';\n\ntype ToggleProps = {\n  kind?: ToggleKind;\n  label: string;\n  checked?: boolean;\n  disabled?: boolean;\n  onChange?: (checked: boolean) => void;\n};\n\nexport function Toggle({ kind = 'checkbox', label, checked, disabled = false, onChange }: ToggleProps) {\n  const handle = (next: boolean) => onChange?.(next);\n\n  if (kind === 'switch') {\n    return (\n      <label className={`toggle toggle-switch ${disabled ? 'toggle-disabled' : ''}`}>\n        <input\n          type=\"checkbox\"\n          role=\"switch\"\n          checked={checked}\n          disabled={disabled}\n          onChange={(event) => handle(event.target.checked)}\n        />\n        <span className=\"toggle-track\"><span className=\"toggle-knob\" /></span>\n        <span className=\"toggle-text\">{label}</span>\n      </label>\n    );\n  }\n\n  return (\n    <label className={`toggle ${disabled ? 'toggle-disabled' : ''}`}>\n      <input\n        type={kind}\n        className=\"toggle-box\"\n        checked={checked}\n        disabled={disabled}\n        onChange={(event) => handle(event.target.checked)}\n      />\n      <span className=\"toggle-text\">{label}</span>\n    </label>\n  );\n}\n",
  "toggle.css": "/* 외부 UI 라이브러리 없이 쓰는 Checkbox·Radio·Switch 스타일. */\n.toggle { display: inline-flex; align-items: center; gap: 9px; font-family: inherit; cursor: pointer; }\n.toggle-text { font-size: 13px; font-weight: 700; color: #334155; }\n.toggle input { margin: 0; cursor: pointer; }\n.toggle-disabled { opacity: 0.5; cursor: not-allowed; }\n.toggle-disabled input { cursor: not-allowed; }\n\n.toggle-box { width: 17px; height: 17px; accent-color: #2563eb; }\n\n/* Switch는 체크박스를 숨기고 트랙과 손잡이를 직접 그린다. */\n.toggle-switch input { position: absolute; opacity: 0; width: 0; height: 0; }\n.toggle-track {\n  position: relative;\n  width: 38px; height: 22px;\n  border-radius: 999px;\n  background: #cbd5e1;\n  transition: background-color 0.18s ease;\n  flex-shrink: 0;\n}\n.toggle-knob {\n  position: absolute; top: 3px; left: 3px;\n  width: 16px; height: 16px;\n  border-radius: 999px;\n  background: #fff;\n  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.25);\n  transition: transform 0.18s ease;\n}\n.toggle-switch input:checked + .toggle-track { background: #2563eb; }\n.toggle-switch input:checked + .toggle-track .toggle-knob { transform: translateX(16px); }\n",
  "tabs.tsx": "import type { ReactNode } from 'react';\nimport './tabs.css';\n\nexport type TabItem = { id: string; label: string; count?: number; disabled?: boolean; panel: ReactNode };\n\ntype TabsProps = { items: TabItem[]; activeId: string; onSelect: (id: string) => void; variant?: 'line' | 'pill'; dense?: boolean };\n\nexport function Tabs({ items, activeId, onSelect, variant = 'line', dense = false }: TabsProps) {\n  const active = items.find((item) => item.id === activeId) ?? items[0];\n  return (\n    <section className={`tabs tabs-${variant}${dense ? ' tabs-dense' : ''}`}>\n      <div className=\"tabs-list\" role=\"tablist\" aria-label=\"콘텐츠 탭\">\n        {items.map((item) => (\n          <button key={item.id} type=\"button\" role=\"tab\" id={`tab-${item.id}`} aria-selected={item.id === active?.id} aria-controls={`panel-${item.id}`} tabIndex={item.id === active?.id ? 0 : -1} disabled={item.disabled} onClick={() => onSelect(item.id)}>\n            <span>{item.label}</span>{item.count != null ? <span className=\"tabs-count\">{item.count}</span> : null}\n          </button>\n        ))}\n      </div>\n      {active ? <div className=\"tabs-panel\" role=\"tabpanel\" id={`panel-${active.id}`} aria-labelledby={`tab-${active.id}`} tabIndex={0}>{active.panel}</div> : null}\n    </section>\n  );\n}\n",
  "tabs.css": "/* 외부 UI 라이브러리 없이 쓰는 Tabs 스타일. Light 테마를 기본으로 한다. */\n.tabs { width: 100%; color: #0f172a; font-family: inherit; }\n.tabs-list { display: flex; gap: 4px; border-bottom: 1px solid #e2e8f0; }\n.tabs-list button { position: relative; display: inline-flex; align-items: center; gap: 7px; padding: 11px 14px; border: 0; background: transparent; color: #64748b; font: inherit; font-size: 13px; font-weight: 800; cursor: pointer; }\n.tabs-list button:hover { color: #1e293b; background: #f8fafc; }\n.tabs-list button[aria-selected='true'] { color: #2563eb; }\n.tabs-list button[aria-selected='true']::after { position: absolute; right: 0; bottom: -1px; left: 0; height: 2px; background: #2563eb; content: ''; }\n.tabs-list button:disabled { color: #cbd5e1; cursor: not-allowed; }\n.tabs-list button:focus-visible, .tabs-panel:focus-visible { outline: 2px solid #2563eb; outline-offset: -2px; }\n.tabs-count { min-width: 18px; padding: 2px 5px; border-radius: 999px; background: #eff6ff; color: #2563eb; font-size: 11px; line-height: 1; text-align: center; }\n.tabs-panel { min-height: 88px; padding: 18px 4px; color: #475569; font-size: 13px; line-height: 1.7; }\n.tabs-pill .tabs-list { padding: 4px; border: 1px solid #e2e8f0; border-radius: 10px; background: #f8fafc; }\n.tabs-pill .tabs-list button { flex: 1 1 0; justify-content: center; border-radius: 7px; }\n.tabs-pill .tabs-list button[aria-selected='true'] { background: #1d4ed8; color: #fff; box-shadow: 0 2px 5px rgba(29, 78, 216, 0.28); }\n.tabs-pill .tabs-list button[aria-selected='true']::after { display: none; }\n.tabs-dense .tabs-list button { padding: 8px 11px; font-size: 12px; }\n.tabs-dense .tabs-panel { min-height: 64px; padding: 12px 4px; }\n",
  "tabs-demo.tsx": "import { useState } from 'react';\nimport { Tabs, type TabItem } from './tabs';\nimport './tabs.css';\n\nconst ITEMS: TabItem[] = [\n  { id: 'overview', label: '개요', count: 3, panel: '현재 작업의 요약과 핵심 상태를 보여 줍니다.' },\n  { id: 'history', label: '이력', count: 12, panel: '같은 대상의 변경 이력을 시간순으로 보여 줍니다.' },\n  { id: 'settings', label: '설정', panel: '현재 맥락에 속한 표시·동작 옵션을 조정합니다.' },\n];\n\nexport function TabsDemo({ variant = 'line', dense = false }: { variant?: 'line' | 'pill'; dense?: boolean }) {\n  const [activeId, setActiveId] = useState('overview');\n  return <Tabs items={ITEMS} activeId={activeId} onSelect={setActiveId} variant={variant} dense={dense} />;\n}\n",
};
